send_email.beforeRequest:
if (!inputs.text && !inputs.html) throw new Error('Please provide either a plain text or HTML body for the email.');
const body = {from: inputs.from, to: inputs.to, subject: inputs.subject};
if (inputs.cc) body.cc = inputs.cc;
if (inputs.bcc) body.bcc = inputs.bcc;
if (inputs.replyTo) body['h:Reply-To'] = inputs.replyTo;
if (inputs.text) body.text = inputs.text;
if (inputs.html) body.html = inputs.html;
request.body = body;
return request;

add_mailing_list_member.beforeRequest:
request.url = request.url.replace(encodeURIComponent(inputs.list), encodeURI(inputs.list).replace(/[?#]/g, encodeURIComponent));
const body = {address: inputs.address, upsert: inputs.upsert === 'true' ? 'yes' : 'no', subscribed: inputs.subscribed === 'false' ? 'no' : 'yes'};
if (inputs.name) body.name = inputs.name;
const vars = inputs.vars ? JSON.parse(inputs.vars) : null;
if (vars) body.vars = JSON.stringify(vars);
request.body = body;
return request;

get_events.beforeRequest:
const max = Math.min(Math.max(inputs.limit === '' ? 100 : Number(inputs.limit), 1), 1000);
request.query.limit = String(Math.min(max, 300));
return request;

