function flat(item) {
  const r = {event: item['event'] ?? null, id: item['id'] ?? null, timestamp: item['timestamp'] ?? null, recipient: item['recipient'] ?? null, domain: item['domain'] ?? null, log_level: item['log-level'] ?? null, severity: item['severity'] ?? null, reason: item['reason'] ?? null};
  const h = item.message && item.message.headers;
  if (h) { r.message_id = h['message-id'] ?? null; r.from = h.from ?? null; r.to = h.to ?? null; r.subject = h.subject ?? null; }
  const d = item['delivery-status'];
  if (d) { r.delivery_status_code = d.code ?? null; r.delivery_status_message = d.message ?? null; r.delivery_status_description = d.description ?? null; }
  r.tags = Array.isArray(item.tags) ? item.tags.join(', ') : null;
  return r;
}
const max = Math.min(Math.max(inputs.limit === '' ? 100 : Number(inputs.limit), 1), 1000);
let all = [].concat(response.items);
let next = (response.paging && response.paging.next) || null;
while (next && all.length < max) {
  const page = call({method: 'GET', url: next});
  if (!page.items || page.items.length === 0) break;
  all = all.concat(page.items);
  next = (page.paging && page.paging.next) || null;
}
const events = all.slice(0, max).map(flat);
