get_domain_stats.beforeRequest:
const events = JSON.parse(inputs.event);
request.url += '?duration=' + encodeURIComponent(inputs.duration) + events.map((e) => '&event=' + encodeURIComponent(e)).join('');
return request;

get_domain_stats.afterResponse:
const t = {accepted: 0, delivered: 0, failed_permanent: 0, failed_temporary: 0, opened: 0, clicked: 0, complained: 0, unsubscribed: 0, stored: 0};
for (const b of response.stats || []) {
  for (const k of ['accepted', 'delivered', 'opened', 'clicked', 'complained', 'unsubscribed', 'stored']) t[k] += (b[k] && b[k].total) || 0;
  t.failed_permanent += (b.failed && b.failed.permanent && b.failed.permanent.total) || 0;
  t.failed_temporary += (b.failed && b.failed.temporary && b.failed.temporary.total) || 0;
}
return {duration: inputs.duration, accepted: t.accepted, delivered: t.delivered, failed_permanent: t.failed_permanent, failed_temporary: t.failed_temporary, failed_total: t.failed_permanent + t.failed_temporary, opened: t.opened, clicked: t.clicked, complained: t.complained, unsubscribed: t.unsubscribed, stored: t.stored};

