delete_bounces_bulk.beforeRequest:
if (inputs.scope === 'single') {
  const address = inputs.address.trim();
  if (!address) throw new Error('An address is required when Scope is "Single address".');
  request.url += '/' + encodeURIComponent(address);
}
return request;

get_domain_health.afterResponse:
